// DRAFT (map-3d-draft branch): 3D rebuild of the Figma campus art.
//
// Two sources of positions:
// - The key places (A1–A5, B1, the track and courts, the lake and its park,
//   the café dome, the footbridge, the statue) are at true scale, from
//   OpenStreetMap checked against the team's GPS points (campusData.ts,
//   generated by scripts/map3d/emit_phase1.py). See fromReal / gpsToWorld.
// - Everything else (outer road, plantation, trees) is still read off
//   public/campus-map.png, measured on the image scaled to 2000 px wide. The
//   art is an isometric drawing, so a point on the ground maps to the flat
//   world plane with one affine transform: the image's left, top and bottom
//   corners of the outer road become the world's (-X,+Z), (-X,-Z) and (+X,+Z)
//   corners. 1 world unit ≈ 10 image px.

import { GPS_POINTS, LANDMARKS } from "@/lib/mapGeo";

import { BUILDINGS_M, DUCK_M, FOOTBRIDGE_M, FOOTPATHS_M, GRASS_M, LAKE_M, PARK_M, type EN, type RectM } from "./campusData";

export type Img = readonly [number, number];
export type World = [number, number]; // [x, z]

const L: Img = [62, 487]; // left corner of the outer road
const U: Img = [818, -479]; // left → top corner
const V: Img = [1013, 618]; // left → bottom corner
const DET = U[0] * V[1] - U[1] * V[0];

export const WORLD_W = 118.7; // along +X (image left → bottom)
export const WORLD_D = 94.8; // along -Z (image left → top)

/** Half size of the diorama slab (campus + the plantation ring around it). */
export const EXTENT = { x: 72, z: 66 };

/** Image pixel (2000-wide art) → world [x, z] on the ground. */
export function toWorld([px, py]: Img): World {
  const dx = px - L[0];
  const dy = py - L[1];
  const a = (dx * V[1] - dy * V[0]) / DET;
  const b = (U[0] * dy - U[1] * dx) / DET;
  return [b * WORLD_W - WORLD_W / 2, WORLD_D / 2 - a * WORLD_D];
}

